import React, { useState, useEffect } from 'react';
import './QuestionList.css';

function QuestionList() {
  const [questions, setQuestions] = useState([]);
  const [expandedId, setExpandedId] = useState(null);

  useEffect(() => {
    fetch('http://localhost:8080/questions')
      .then(res => res.json())
      .then(data => setQuestions(data))
      .catch(err => console.error('Eroare:', err));
  }, []);

  const toggleExpand = (id) => {
    setExpandedId(prevId => (prevId === id ? null : id));
  };

  return (
    <div className="question-list-container">
      <h2>Întrebări</h2>
      {questions.map((q) => (
        <div key={q.id} className="question-item">
          <h3>{q.title}</h3>
          <p><strong>Autor:</strong> {q.user?.username}</p>
          <p><strong>Etichete:</strong> {q.questionTags?.map(tag => (
            <span className="tag" key={tag.id}>{tag.tag.name}</span>
          ))}</p>
          <button className="see-question-btn" onClick={() => toggleExpand(q.id)}>
            {expandedId === q.id ? 'Ascunde detalii' : 'Vezi întrebarea și răspunsurile'}
          </button>

          {expandedId === q.id && (
            <div className="answers-section">
              <p><strong>Text întrebare:</strong> {q.text}</p>
              <p><em>(Aici pot apărea răspunsurile dacă facem fetch separat)</em></p>
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

export default QuestionList;
